    AND h.`dkmc` LIKE CONCAT('%', #{q.dkmc}, '%')


    AND h.`facility_id` = #{q.facilityId}


    AND h.`handover_type` = #{q.handoverType}


    AND h.`status` = #{q.status}


    AND h.`agreement_date` >= #{q.beginAgreementDate}


    AND h.`agreement_date` <= #{q.endAgreementDate}


    AND h.`handover_date` >= #{q.beginHandoverDate}


    AND h.`handover_date` <= #{q.endHandoverDate}


    AND h.`maintenance_end` >= #{q.beginMaintenanceEnd}


    AND h.`maintenance_end` <= #{q.endMaintenanceEnd}


