            AND h.`archive_id` IS NOT NULL


            AND h.`archive_id` IS NULL




    AND h.`create_time` >= CONCAT(#{q.beginCreateTime}, ' 00:00:00')


    AND h.`create_time` <= CONCAT(#{q.endCreateTime}, ' 23:59:59')


    AND (
        h.`handover_no` LIKE CONCAT('%', #{q.keyword}, '%')
        OR h.`road_name` LIKE CONCAT('%', #{q.keyword}, '%')
        OR h.`crzdbh` LIKE CONCAT('%', #{q.keyword}, '%')
        OR h.`dkmc` LIKE CONCAT('%', #{q.keyword}, '%')
